-- ════════════════════════════════════════════════════════
-- O Crime de Caatedrum — conteúdo (regras, textos, casos).
-- GERADO por scripts/caatedrum-conteudo.mjs a partir de jogos/caatedrum/.
-- Não edite aqui: edite os JSON e rode o script de novo.
-- Tem a solução: só as funções do jogo leem (ninguém chama direto).
-- ════════════════════════════════════════════════════════

create or replace function public.caat_content()
returns jsonb
language sql
immutable
set search_path = public
as $fn$
  select $conteudo${"regras":{"_leia":"Regras de O Crime de Caatedrum. 'original' = igual ao jogo de tabuleiro; 'sessao' = extras da nossa sessão de RPG (0 ou null desliga). Mudou algo? Rode: node scripts/caatedrum-conteudo.mjs","original":{"jogadores":4,"maoInicial":6,"referenciasPorPedido":2,"tiposDeReferencia":["suspeito","sala"],"ofertaPodeTerVariasCartas":true,"ofertaPrecisaCitarAoMenos":1,"pagamentoMinimoIgualAoValor":true,"trocaComVariosOfertantes":true,"compraQuandoNinguemOferta":3,"descartarAteFicarCom":3,"completarMaoAte":6,"aoReembaralharRevelar":3,"erroNaSolucaoFicaForaDe":1,"baralhoPorCaso":70,"ordem":"anti-horaria","inicialPassaPara":"proximo-na-ordem"},"sessao":{"rodadasMax":7,"timerPedirSegundos":120,"timerOfertaSegundos":60,"timerTrocaSegundos":90,"timerSolucaoSegundos":90,"fichasInterrogatorio":0,"pontosVitoria":3,"pontosPorAcertoSecundario":1},"niveis":{"2":{"fichasInterrogatorioExtra":1},"3":{"maoInicialExtra":1,"descartaNaPrimeiraRodada":1},"4":{"pedidoExtraPorPartida":1},"5":{"verOfertaDevolvidaPorPartida":1}}},"textos":{"nome":"O Crime de Caatedrum","chamada":"A mesa de Caatedrum está posta","abertura":["É a Noite da Prova dos Mestres. Nas Matinas, o Mestre Orlan, Mestre da Moeda, foi achado morto em seu gabinete.","Seis suspeitos, quatro criados e uma guarda que anotou tudo. Cada um de vocês guarda pedaços do que aconteceu — e só troca o que sabe por algo de igual valor.","Quem desvendar primeiro quem matou, por quê, como e se teve cúmplice, ganha a prova."],"consentimento":["O Mestre pode interferir durante a partida: mandar um bilhete da torre para o seu caderno (que pode ser falso), borrar parte do caderno com tinta por 60 segundos ou trocar o apelido de dois jogadores por 30 segundos. Tudo fica registrado e é mostrado no fim.","Qualquer um pode apertar Pausar a qualquer momento — o jogo para para todos."],"niveis":[{"n":1,"nome":"Aprendiz","vantagem":"Nenhuma vantagem."},{"n":2,"nome":"Copista","vantagem":"Uma ficha de interrogatório a mais."},{"n":3,"nome":"Escrivão","vantagem":"Começa com 7 cartas e descarta 1 na primeira rodada."},{"n":4,"nome":"Inquisidor","vantagem":"Uma vez por partida, pode pedir duas vezes na mesma rodada."},{"n":5,"nome":"Mestre","vantagem":"Uma vez por partida, vê uma carta que acabou de voltar para quem a ofertou."}],"niveisAviso":"Quanto maior o nível, maior a vantagem — e maior o castigo no RPG se você perder.","assentos":[{"cor":"azul","emblema":"torre"},{"cor":"vermelho","emblema":"chave"},{"cor":"verde","emblema":"folha"},{"cor":"roxo","emblema":"sino"}]},"casos":{"caso1":{"_leia":"Caso 1 de O Crime de Caatedrum. 'publico' qualquer jogador vê; 'secreto' fica só no banco (nunca vai pro navegador). As cartas (baralho) entram no marco 3.","publico":{"titulo":"A morte do Mestre da Moeda","vitima":"Mestre Orlan","local_do_corpo":"Ga","sinos":[{"id":"ve","nome":"Vésperas","quando":"anoitecer"},{"id":"co","nome":"Completas","quando":"noite — a hora do crime"},{"id":"ma","nome":"Matinas","quando":"antes do amanhecer — o corpo é achado"}],"sino_do_crime":"co","suspeitos":[{"id":"dessa","nome":"Dessa Vael","perfil":"Estudante três vezes reprovada sob Orlan. Orgulhosa.","motivos":["vinganca","ambicao","segredo"]},{"id":"marrow","nome":"Marrow","perfil":"Estudante veterano há trinta anos. Calado, sempre com tinta nos dedos.","motivos":["amor","vinganca","segredo"]},{"id":"gorm","nome":"Gorm Haldt","perfil":"Aspirante a Mestre da Guerra, jogador de dados.","motivos":["divida","ambicao","vinganca"]},{"id":"hilde","nome":"Hilde Brannoc","perfil":"Copista favorita de Orlan. Ambiciosa.","motivos":["ambicao","amor","segredo"]},{"id":"oswin","nome":"Oswin Prym","perfil":"Bibliotecário e guardião das chaves.","motivos":["segredo","fe","divida"]},{"id":"quenn","nome":"Irmã Quenn","perfil":"Capelã que ouve as confissões da torre.","motivos":["fe","segredo","amor"]}],"criadagem":[{"id":"sineiro","nome":"Sineiro"},{"id":"porteiro","nome":"Porteiro"},{"id":"cozinheira","nome":"Mãe Berta, a cozinheira"},{"id":"guarda","nome":"Guarda-noturno"}],"salas":[{"id":"P","nome":"Portão"},{"id":"Pa","nome":"Pátio dos Sinos"},{"id":"Ca","nome":"Capela"},{"id":"Re","nome":"Refeitório"},{"id":"Co","nome":"Cozinhas"},{"id":"Do","nome":"Dormitórios"},{"id":"Bi","nome":"Grande Biblioteca"},{"id":"Sc","nome":"Scriptorium"},{"id":"Ga","nome":"Gabinete do Mestre da Moeda"},{"id":"Cn","nome":"Sala do Conselho"},{"id":"Cm","nome":"Torre do Sino"},{"id":"Ci","nome":"Cisternas"},{"id":"Ap","nome":"Ala Proibida"},{"id":"Sp","nome":"Galeria dos Espelhos"}],"ligacoes":[["P","Pa"],["Pa","Ca"],["Pa","Re"],["Pa","Bi"],["Pa","Cm"],["Re","Co"],["Re","Do"],["Do","Bi"],["Bi","Sc"],["Bi","Ap"],["Sc","Ga"],["Ga","Cn"],["Cn","Sp"],["Cn","Cm"],["Co","Ci"],["Ci","Ap"],["Ca","Sp"]],"regra_movimento":"Entre dois sinos, uma pessoa fica na mesma sala ou vai a uma sala ligada à sua.","motivos":[{"id":"ambicao","nome":"Ambição"},{"id":"vinganca","nome":"Vingança"},{"id":"divida","nome":"Dívida"},{"id":"segredo","nome":"Segredo a esconder"},{"id":"fe","nome":"Fé fanática"},{"id":"amor","nome":"Amor perdido"}],"sinais":[{"id":"sangue","nome":"Sangue no chão"},{"id":"ferida","nome":"Ferida aberta"},{"id":"labios","nome":"Lábios negros"},{"id":"pescoco","nome":"Marca roxa no pescoço"},{"id":"ossos","nome":"Ossos partidos"},{"id":"intacto","nome":"Pele sem nenhum corte"}],"armas":[{"id":"punhal","nome":"Punhal de escriba","morte":"apunhalado","sinais":["sangue","ferida"]},{"id":"tinta","nome":"Tinta de ferro envenenada","morte":"envenenado","sinais":["labios","intacto"]},{"id":"corda","nome":"Corda do sino","morte":"estrangulado","sinais":["pescoco","intacto"]},{"id":"candelabro","nome":"Candelabro de ferro","morte":"golpe na cabeça","sinais":["sangue","ossos"]},{"id":"besta","nome":"Besta da guarda","morte":"flechado","sinais":["ferida","ossos"]},{"id":"queda","nome":"Empurrado do campanário","morte":"queda","sinais":["ossos","intacto"]}],"perguntas":["quem","porque","como","cumplice"]},"secreto":{"solucao":{"quem":"marrow","porque":"amor","como":"tinta","cumplice":"oswin"},"mundo":{"marrow":["Sc","Ga","Sc"],"hilde":["Sc","Sc","Sc"],"dessa":["Do","Bi","Do"],"gorm":["Re","Co","Re"],"oswin":["Bi","Bi","Bi"],"quenn":["Ca","Ca","Pa"],"sineiro":["Cm","Cm","Cm"],"porteiro":["P","P","P"],"cozinheira":["Co","Co","Co"],"guarda":["Cn","Cn","Ga"]}}}}}$conteudo$::jsonb
$fn$;

revoke all on function public.caat_content() from public, anon, authenticated;
